import React, { useState } from 'react';
import Header from './components/Header';
import HeroSection from './components/HeroSection';
import BrowseByRoom from './components/BrowseByRoom';
import LatestStories from './components/LatestStories';
import PhotosPage from './components/PhotosPage';
import FindProfessionalsPage from './components/FindProfessionalsPage';
import './App.css';

function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [selectedCategory, setSelectedCategory] = useState('all');

  const handleNavigate = (page, category = 'all') => {
    setCurrentPage(page);
    setSelectedCategory(category);
  };

  const renderCurrentPage = () => {
    switch (currentPage) {
      case 'photos':
        return <PhotosPage selectedCategory={selectedCategory} />;
      case 'professionals':
        return <FindProfessionalsPage />;
      case 'home':
      default:
        return (
          <>
            <HeroSection onNavigate={handleNavigate} />
            <BrowseByRoom onNavigate={handleNavigate} />
            <LatestStories />
          </>
        );
    }
  };

  return (
    <div className="App">
      <Header onNavigate={handleNavigate} currentPage={currentPage} />
      {renderCurrentPage()}
    </div>
  );
}

export default App;
